<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>YouTube B-roll Coverage Dealer</title>
  <style>
    :root {
      --bg: #101418;
      --panel: #182028;
      --panel-2: #1f2a34;
      --text: #f3f7fb;
      --muted: #aebac6;
      --line: #324251;
      --accent: #8dd7ff;
      --accent-2: #bff0c2;
      --warn: #ffd18a;
      --bad: #ff9e9e;
      --shadow: 0 18px 42px rgba(0,0,0,.28);
      --radius: 18px;
    }

    * {
      box-sizing: border-box;
      min-width: 0;
    }

    html {
      width: 100%;
    }

    body {
      margin: 0;
      width: 100%;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(141,215,255,.18), transparent 34rem),
        linear-gradient(180deg, #101418, #0c1014 70%);
      color: var(--text);
      line-height: 1.45;
    }

    button,
    input,
    textarea,
    select {
      font: inherit;
      max-width: 100%;
    }

    button {
      border: 0;
      border-radius: 14px;
      padding: .82rem .92rem;
      background: var(--accent);
      color: #071018;
      font-weight: 750;
      cursor: pointer;
      width: 100%;
      white-space: normal;
      overflow-wrap: anywhere;
      touch-action: manipulation;
    }

    button.secondary {
      background: #263543;
      color: var(--text);
      border: 1px solid var(--line);
    }

    button.ghost {
      background: transparent;
      color: var(--accent);
      border: 1px solid rgba(141,215,255,.5);
    }

    button.danger {
      background: #3a2429;
      color: #ffd3d3;
      border: 1px solid #70414b;
    }

    button:active {
      transform: translateY(1px);
    }

    input,
    textarea,
    select {
      width: 100%;
      border: 1px solid var(--line);
      background: #0f151b;
      color: var(--text);
      border-radius: 14px;
      padding: .82rem .88rem;
      outline: none;
    }

    textarea {
      min-height: 108px;
      resize: vertical;
    }

    input::placeholder,
