    .badge {
      display: block;
      width: fit-content;
      max-width: 100%;
      border: 1px solid rgba(141,215,255,.45);
      color: var(--accent);
      border-radius: 999px;
      padding: .42rem .66rem;
      font-size: .8rem;
      overflow-wrap: anywhere;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 13vw, 4.6rem);
      line-height: .94;
      letter-spacing: -.06em;
      overflow-wrap: anywhere;
