    h1 span {
      display: block;
    }

    h2 {
      margin: 0;
      font-size: 1.08rem;
      letter-spacing: -.01em;
    }

    p {
      margin: 0;
      color: var(--muted);
      overflow-wrap: anywhere;
    }

    .panel {
      background: rgba(24,32,40,.94);
