    .status-bar {
      display: grid;
      gap: 8px;
      padding: 12px;
      border-radius: 16px;
      background: #111820;
      border: 1px solid var(--line);
    }

    .score-line {
      display: grid;
      gap: 6px;
    }

    progress {
      width: 100%;
      height: 18px;
      border: 0;
      border-radius: 999px;
      overflow: hidden;
      background: #0c1116;
    }

    progress::-webkit-progress-bar {
      background: #0c1116;
      border-radius: 999px;
    }

    progress::-webkit-progress-value {
      background: linear-gradient(90deg, var(--bad), var(--warn), var(--accent-2));
      border-radius: 999px;
    }

    progress::-moz-progress-bar {
      background: linear-gradient(90deg, var(--bad), var(--warn), var(--accent-2));
      border-radius: 999px;
    }

    .pill-list {
      display: grid;
      grid-template-columns: 1fr;
      gap: 8px;
    }

    .pill {
      display: block;
      width: 100%;
      border-radius: 14px;
      padding: .72rem .78rem;
      background: #111820;
      border: 1px solid var(--line);
      color: var(--muted);
      overflow-wrap: anywhere;
    }

    .pill.good {
      color: #dfffe2;
      border-color: rgba(191,240,194,.45);
      background: rgba(40,79,44,.35);
    }

    .pill.warn {
      color: #ffe6b8;
      border-color: rgba(255,209,138,.55);
      background: rgba(88,65,25,.35);
    }

    .pill.bad {
      color: #ffd4d4;
      border-color: rgba(255,158,158,.55);
      background: rgba(88,34,42,.35);
