    .item-card,
    .shot-card,
    .slot-card {
      border: 1px solid var(--line);
      background: var(--panel-2);
      border-radius: 16px;
      padding: 12px;
      display: grid;
      gap: 10px;
      overflow-wrap: anywhere;
    }

    .slot-card {
      background: rgba(31,42,52,.78);
    }

    .slot-head {
      display: grid;
      gap: 4px;
      padding-bottom: 4px;
      border-bottom: 1px solid rgba(255,255,255,.08);
    }

    .slot-title {
      font-weight: 850;
      font-size: 1.02rem;
    }

    .slot-hint {
      color: var(--muted);
      font-size: .88rem;
    }

    .meta-line {
      display: grid;
      grid-template-columns: 1fr;
      gap: 6px;
      color: var(--muted);
      font-size: .88rem;
    }

    .tag {
      display: block;
      width: fit-content;
      max-width: 100%;
      padding: .34rem .55rem;
      border-radius: 999px;
      background: #111820;
      border: 1px solid var(--line);
      color: var(--accent);
      font-size: .78rem;
      font-weight: 750;
      overflow-wrap: anywhere;
    }

    .tag.claim {
      color: var(--warn);
    }

    .tag.scene {
      color: var(--accent-2);
    }

    .tag.critical {
      color: #ffd4d4;
      border-color: rgba(255,158,158,.5);
    }

    .empty {
      border: 1px dashed var(--line);
      color: var(--muted);
      border-radius: 16px;
      padding: 14px;
      background: rgba(15,21,27,.5);
      overflow-wrap: anywhere;
    }

    .check-preview {
      min-height: 240px;
      white-space: pre-wrap;
      overflow-wrap: anywhere;
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: .86rem;
      color: #d8e4ee;
      background: #0c1116;
      border: 1px solid var(--line);
      border-radius: 16px;
      padding: 12px;
    }

    .toast {
      position: fixed;
      left: 14px;
      right: 14px;
      bottom: 14px;
      background: #e9fbff;
      color: #071018;
      padding: .9rem 1rem;
      border-radius: 16px;
      box-shadow: var(--shadow);
      font-weight: 800;
      display: none;
      overflow-wrap: anywhere;
      z-index: 5;
    }

    .toast.show {
      display: block;
    }

    @media (min-width: 740px) {
      .wrap,
      .hero {
        padding-left: 22px;
        padding-right: 22px;
      }

      .grid.two {
        grid-template-columns: 1fr 1fr;
      }

      .grid.three {
        grid-template-columns: repeat(3, 1fr);
      }

      .button-row {
        grid-template-columns: repeat(3, 1fr);
      }

      .mini-row {
        grid-template-columns: 1fr 1fr;
      }

      .slots-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px;
      }
    }
  </style>
</head>
<body>
  <header class="hero">
    <div class="hero-inner">
      <span class="badge">offline · local only · phone-first</span>
      <h1>
        <span>YouTube</span>
        <span>B-roll</span>
        <span>Coverage Dealer</span>
      </h1>
      <p>Turn a loose premise into scenes, claims, B-roll cards, coverage warnings, and a copyable shoot checklist.</p>
    </div>
  </header>

  <main class="wrap">
    <section class="panel" aria-labelledby="setup-title">
      <div class="panel-head">
        <h2 id="setup-title">1. Premise</h2>
        <p>Keep it rough. The board uses this to seed hook, texture, proof, and CTA shots.</p>
      </div>

      <div class="grid two">
        <label class="field">
          <span>Loose video premise</span>
          <textarea id="premise" placeholder="Example: I tried planning my week backward from Friday outcomes, and it exposed where I was overloading each day."></textarea>
        </label>

        <div class="grid">
          <label class="field">
            <span>Audience or viewer problem</span>
            <input id="audience" placeholder="Example: solo creators who forget pickup shots">
          </label>

          <label class="field">
            <span>Video style</span>
            <select id="style">
              <option value="practical">Practical explainer</option>
              <option value="story">Story or vlog</option>
              <option value="review">Review or comparison</option>
              <option value="essay">Video essay</option>
              <option value="tutorial">Tutorial</option>
            </select>
          </label>

          <label class="field">
            <span>Main viewer action</span>
            <input id="action" placeholder="Example: copy the checklist, try the method, watch next video">
          </label>
        </div>
      </div>
    </section>

    <section class="panel" aria-labelledby="scene-title">
      <div class="panel-head">
        <h2 id="scene-title">2. Scenes and claims</h2>
        <p>Add the beats that need visual support. Claims with weak evidence will be flagged.</p>
      </div>

      <div class="grid two">
        <div class="grid">
          <div class="grid two">
            <label class="field">
              <span>Type</span>
              <select id="itemKind">
                <option value="scene">Scene</option>
                <option value="claim">Claim</option>
              </select>
            </label>

            <label class="field">
              <span>Priority</span>
              <select id="itemPriority">
                <option value="normal">Normal</option>
                <option value="key">Key coverage</option>
              </select>
            </label>
          </div>

          <label class="field">
            <span>Scene or claim title</span>
            <input id="itemTitle" placeholder="Example: Show the messy starting point">
          </label>

          <label class="field">
            <span>Notes</span>
            <textarea id="itemNotes" placeholder="What needs to be seen, understood, or believed?"></textarea>
          </label>

          <label class="field">
            <span>Evidence note, especially for claims</span>
            <textarea id="itemEvidence" placeholder="Example: screen recording, data point, receipt, side-by-side, quote, before/after"></textarea>
          </label>

          <div class="button-row">
            <button id="addItem">Add scene or claim</button>
            <button id="shotForLast" class="secondary">Add and make shots</button>
            <button id="clearItemFields" class="ghost">Clear fields</button>
          </div>
        </div>

        <div class="grid">
          <label class="field">
            <span>Bulk add, one per line</span>
            <textarea id="bulkItems" placeholder="scene: cold open problem&#10;claim: creators miss B-roll because they outline words, not visuals&#10;scene: proof example with timeline"></textarea>
          </label>

          <div class="button-row">
            <button id="importItems" class="secondary">Import lines</button>
            <button id="sampleBoard" class="ghost">Load sample</button>
            <button id="resetBoard" class="danger">Reset board</button>
          </div>
        </div>
      </div>

      <div id="items" class="item-list" aria-live="polite"></div>
    </section>

    <section class="panel" aria-labelledby="shots-title">
      <div class="panel-head">
        <h2 id="shots-title">3. B-roll card dealer</h2>
        <p>Generate cards, then deal them into intro, body, proof, and CTA. You can edit every card.</p>
      </div>

      <div class="button-row">
        <button id="generateShots">Build missing B-roll cards</button>
        <button id="dealShots" class="secondary">Deal cards into slots</button>
        <button id="clearShots" class="danger">Clear shot cards</button>
      </div>

      <div class="grid two">
        <label class="field">
          <span>Manual shot card</span>
          <input id="manualShotLabel" placeholder="Example: close-up of checklist being marked">
        </label>

        <label class="field">
          <span>Manual slot</span>
          <select id="manualShotSlot">
            <option value="pool">Undealt pool</option>
            <option value="intro">Intro</option>
            <option value="body">Body</option>
            <option value="proof">Proof</option>
            <option value="cta">CTA</option>
          </select>
        </label>
      </div>

      <label class="field">
        <span>Manual shot detail</span>
        <textarea id="manualShotDetail" placeholder="Frame, prop, screen, motion, or pickup detail."></textarea>
      </label>

      <div class="button-row">
        <button id="addManualShot" class="secondary">Add manual shot</button>
        <button id="markAllNeeded" class="ghost">Mark all as needed</button>
        <button id="markDealtShot" class="ghost">Mark dealt as shot</button>
      </div>
    </section>

    <section class="panel" aria-labelledby="coverage-title">
      <div class="panel-head">
        <h2 id="coverage-title">4. Coverage check</h2>
        <p>Use this as the pickup warning system before filming or editing.</p>
      </div>

      <div id="coverage" class="status-bar"></div>
      <div id="issueList" class="pill-list"></div>
    </section>

    <section class="panel" aria-labelledby="slot-title">
      <div class="panel-head">
        <h2 id="slot-title">5. Slot board</h2>
        <p>Tap a card’s slot menu to move it. Use status to separate needed, shot, and skipped footage.</p>
      </div>

      <div id="slots" class="slots-grid slot-stack"></div>
    </section>

    <section class="panel" aria-labelledby="checklist-title">
      <div class="panel-head">
        <h2 id="checklist-title">6. Shoot checklist</h2>
        <p>Copy this into notes before shooting or download it as a text file.</p>
      </div>

      <div class="button-row">
        <button id="copyChecklist">Copy checklist</button>
        <button id="downloadChecklist" class="secondary">Download .txt</button>
        <button id="downloadJson" class="ghost">Download board data</button>
      </div>

      <pre id="checklist" class="check-preview"></pre>
    </section>
  </main>

  <div id="toast" class="toast" role="status" aria-live="polite"></div>

  <script>
    (function () {
      "use strict";

      var STORE_KEY = "youtube-broll-coverage-dealer-v1";

      var slotDefs = [
        { id: "pool", name: "Undealt pool", hint: "Cards not placed yet." },
        { id: "intro", name: "Intro", hint: "Hook, problem texture, setup, stakes." },
        { id: "body", name: "Body", hint: "Process, scenes, transitions, examples." },
        { id: "proof", name: "Proof", hint: "Receipts, screen captures, data, before/after." },
        { id: "cta", name: "CTA", hint: "Result, next step, subscribe, watch next." }
      ];

      var state = {
        premise: "",
        audience: "",
        style: "practical",
        action: "",
        items: [],
        shots: []
      };

      var ids = {};

      function byId(id) {
        return document.getElementById(id);
      }

      function uid(prefix) {
        return prefix + "_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 7);
      }

      function clean(value) {
        return String(value || "").trim();
      }

      function oneLine(value) {
        return clean(value).replace(/\s+/g, " ");
      }

      function node(tag, attrs) {
        var el = document.createElement(tag);
        attrs = attrs || {};

        Object.keys(attrs).forEach(function (key) {
          var value = attrs[key];

          if (key === "class") {
            el.className = value;
          } else if (key === "text") {
            el.textContent = value;
          } else if (key === "value") {
            el.value = value;
          } else if (key === "type") {
            el.type = value;
          } else if (key === "placeholder") {
            el.placeholder = value;
          } else if (key === "ariaLabel") {
            el.setAttribute("aria-label", value);
          } else if (key.indexOf("on") === 0 && typeof value === "function") {
            el.addEventListener(key.slice(2).toLowerCase(), value);
          } else {
            el.setAttribute(key, value);
          }
        });

        for (var i = 2; i < arguments.length; i += 1) {
          appendChild(el, arguments[i]);
        }

        return el;
      }

      function appendChild(parent, child) {
        if (Array.isArray(child)) {
          child.forEach(function (part) {
            appendChild(parent, part);
          });
          return;
        }

        if (child === null || child === undefined) {
          return;
        }

        if (child.nodeType) {
          parent.appendChild(child);
          return;
        }

        parent.appendChild(document.createTextNode(String(child)));
      }

      function option(value, text) {
        var opt = document.createElement("option");
        opt.value = value;
        opt.textContent = text;
        return opt;
      }

      function makeSelect(currentValue, choices, onChange) {
        var select = node("select");
        choices.forEach(function (choice) {
          select.appendChild(option(choice.value, choice.text));
        });
        select.value = currentValue;
        select.addEventListener("change", function () {
          onChange(select.value);
        });
        return select;
      }

      function labeled(labelText, control) {
        var wrap = node("label", { class: "field" });
        wrap.appendChild(node("span", { text: labelText }));
        wrap.appendChild(control);
        return wrap;
      }

      function load() {
        try {
          var raw = localStorage.getItem(STORE_KEY);
          if (!raw) {
            return;
          }

          var saved = JSON.parse(raw);
          if (saved && typeof saved === "object") {
            state.premise = saved.premise || "";
            state.audience = saved.audience || "";
            state.style = saved.style || "practical";
            state.action = saved.action || "";
            state.items = Array.isArray(saved.items) ? saved.items : [];
            state.shots = Array.isArray(saved.shots) ? saved.shots : [];
          }
        } catch (err) {
          showToast("Saved data could not be loaded.");
        }
      }

      function save() {
        try {
          localStorage.setItem(STORE_KEY, JSON.stringify(state));
        } catch (err) {
          showToast("Local save failed in this browser.");
        }
      }

      function syncSetupFields() {
        ids.premise.value = state.premise;
        ids.audience.value = state.audience;
        ids.style.value = state.style;
        ids.action.value = state.action;
      }

      function bindSetup() {
        ids.premise.addEventListener("input", function () {
          state.premise = ids.premise.value;
          save();
          renderAnalysisOnly();
        });

        ids.audience.addEventListener("input", function () {
          state.audience = ids.audience.value;
          save();
          renderAnalysisOnly();
        });

        ids.style.addEventListener("change", function () {
          state.style = ids.style.value;
          save();
          renderAnalysisOnly();
        });

        ids.action.addEventListener("input", function () {
          state.action = ids.action.value;
          save();
          renderAnalysisOnly();
        });
      }

      function readItemFields() {
        return {
          kind: ids.itemKind.value,
          priority: ids.itemPriority.value,
          title: clean(ids.itemTitle.value),
          notes: ids.itemNotes.value.trim(),
          evidence: ids.itemEvidence.value.trim()
        };
      }

      function clearItemFields() {
        ids.itemKind.value = "scene";
        ids.itemPriority.value = "normal";
        ids.itemTitle.value = "";
        ids.itemNotes.value = "";
        ids.itemEvidence.value = "";
      }

      function addItemFromFields(makeShots) {
        var data = readItemFields();

        if (!data.title && !data.notes && !data.evidence) {
          showToast("Add a title, note, or evidence first.");
          return null;
        }

        if (!data.title) {
          data.title = data.kind === "claim" ? "Untitled claim" : "Untitled scene";
        }

        var item = {
          id: uid("item"),
          kind: data.kind,
          priority: data.priority,
          title: data.title,
          notes: data.notes,
          evidence: data.evidence
        };

        state.items.push(item);
        clearItemFields();

        if (makeShots) {
          generateShotsForItem(item);
        }

        save();
        renderAll();
        return item;
      }

      function importBulkItems() {
        var raw = ids.bulkItems.value;
        var lines = raw.split(/\r?\n/).map(clean).filter(Boolean);

        if (!lines.length) {
          showToast("Paste one scene or claim per line first.");
          return;
        }

        lines.forEach(function (line) {
          var kind = "scene";
          var title = line;
          var notes = "";

          var typed = line.match(/^(scene|claim)\s*[:\-]\s*(.+)$/i);
          if (typed) {
            kind = typed[1].toLowerCase();
            title = typed[2].trim();
          } else if (/prove|evidence|claim|because|data|stat|receipt|source/i.test(line)) {
            kind = "claim";
          }

          if (title.length > 92) {
            notes = title;
            title = title.slice(0, 92).trim();
          }

          state.items.push({
            id: uid("item"),
            kind: kind,
            priority: kind === "claim" ? "key" : "normal",
            title: title,
            notes: notes,
            evidence: ""
          });
        });

        ids.bulkItems.value = "";
        save();
        renderAll();
        showToast("Imported " + lines.length + " scenes or claims.");
      }

      function removeItem(itemId) {
        state.items = state.items.filter(function (item) {
          return item.id !== itemId;
        });
        state.shots = state.shots.filter(function (shot) {
          return shot.sourceId !== itemId;
        });
        save();
        renderAll();
      }

      function getItem(itemId) {
        return state.items.find(function (item) {
          return item.id === itemId;
        });
      }

      function sourceTitle(sourceId) {
        if (sourceId === "premise") {
          return "Premise";
        }

        if (sourceId === "manual") {
          return "Manual card";
        }

        var item = getItem(sourceId);
        return item ? item.title : "Removed source";
      }

      function addShot(sourceId, type, label, detail, slot, critical) {
        var duplicate = state.shots.some(function (shot) {
          return shot.sourceId === sourceId && shot.type === type && shot.label === label;
        });

        if (duplicate) {
          return null;
        }

        var shot = {
          id: uid("shot"),
          sourceId: sourceId,
          type: type,
          label: label,
          detail: detail,
          slot: slot || "pool",
          status: "needed",
          critical: Boolean(critical)
        };

        state.shots.push(shot);
        return shot;
      }

