      function dealShots() {
        if (!state.shots.length) {
          generateAllMissingShots();
        }

        state.shots.forEach(function (shot) {
          if (shot.status === "skip") {
            return;
          }

          var hay = (shot.type + " " + shot.label + " " + shot.detail).toLowerCase();

          if (/cta|end-frame|next step|subscribe|watch next|viewer action/.test(hay)) {
            shot.slot = "cta";
          } else if (/proof|trust|evidence|receipt|source|data|screen|comparison|before\/after|chart/.test(hay)) {
            shot.slot = "proof";
          } else if (/hook|cold|problem|opening|stakes/.test(hay)) {
            shot.slot = "intro";
          } else {
            shot.slot = "body";
          }
        });

        save();
        renderAll();
        showToast("Cards dealt into slots.");
