      function getSlotCounts() {
        var counts = {};
        slotDefs.forEach(function (slot) {
          counts[slot.id] = 0;
        });

        state.shots.forEach(function (shot) {
          if (shot.status !== "skip" && counts.hasOwnProperty(shot.slot)) {
            counts[shot.slot] += 1;
          }
        });

        return counts;
      }

      function analyze() {
        var issues = [];
        var score = 100;
        var counts = getSlotCounts();
        var active = state.shots.filter(function (shot) {
          return shot.status !== "skip";
        });

        function addIssue(text, severity) {
          issues.push({ text: text, severity: severity });
          if (severity === "bad") {
            score -= 13;
          } else if (severity === "warn") {
            score -= 8;
          } else {
            score -= 4;
          }
        }

        if (!clean(state.premise)) {
          addIssue("Premise is empty, so hook and CTA shots are generic.", "bad");
        }

        if (!state.items.length) {
          addIssue("No scenes or claims have been added.", "bad");
        }

        if (!state.shots.length) {
          addIssue("No B-roll cards exist yet.", "bad");
        }

        ["intro", "body", "proof", "cta"].forEach(function (slotId) {
          if (!counts[slotId]) {
            addIssue(slotName(slotId) + " slot has no active B-roll cards.", slotId === "proof" ? "bad" : "warn");
          }
        });

        if (counts.pool > 0) {
          addIssue(counts.pool + " active card" + (counts.pool === 1 ? " is" : "s are") + " still undealt.", "warn");
        }

        var claims = state.items.filter(function (item) {
          return item.kind === "claim";
        });

        claims.forEach(function (claim) {
          if (!clean(claim.evidence)) {
            addIssue("Claim needs an evidence note: " + claim.title, "bad");
          }
        });

        state.items.forEach(function (item) {
          var hasAssignedShot = active.some(function (shot) {
            return shot.sourceId === item.id && shot.slot !== "pool";
          });

          if (!hasAssignedShot) {
            addIssue(item.kind.charAt(0).toUpperCase() + item.kind.slice(1) + " has no assigned B-roll: " + item.title, item.priority === "key" ? "bad" : "warn");
          }
        });

        var criticalUndealt = active.filter(function (shot) {
          return shot.critical && shot.slot === "pool";
        });

        if (criticalUndealt.length) {
          addIssue(criticalUndealt.length + " critical card" + (criticalUndealt.length === 1 ? " is" : "s are") + " still undealt.", "bad");
        }

        var neededCritical = active.filter(function (shot) {
          return shot.critical && shot.status === "needed";
        });

        if (neededCritical.length) {
          addIssue(neededCritical.length + " critical card" + (neededCritical.length === 1 ? " still needs" : "s still need") + " to be shot.", "warn");
        }

        score = Math.max(0, Math.min(100, score));

        return {
          score: score,
          issues: issues,
          counts: counts
        };
      }

      function slotName(slotId) {
        var found = slotDefs.find(function (slot) {
          return slot.id === slotId;
        });
        return found ? found.name : slotId;
      }

      function renderCoverage() {
        var result = analyze();
        var mount = ids.coverage;
        mount.replaceChildren();

        var scoreText = "Coverage score: " + result.score + "/100";
        var line = node("div", { class: "score-line" });
        line.appendChild(node("div", { text: scoreText }));
        line.appendChild(node("progress", { value: String(result.score), max: "100", ariaLabel: scoreText }));
        mount.appendChild(line);

        var counts = node("div", { class: "pill-list" });
        counts.appendChild(node("span", { class: result.counts.intro ? "pill good" : "pill warn", text: "Intro cards: " + result.counts.intro }));
        counts.appendChild(node("span", { class: result.counts.body ? "pill good" : "pill warn", text: "Body cards: " + result.counts.body }));
        counts.appendChild(node("span", { class: result.counts.proof ? "pill good" : "pill bad", text: "Proof cards: " + result.counts.proof }));
        counts.appendChild(node("span", { class: result.counts.cta ? "pill good" : "pill warn", text: "CTA cards: " + result.counts.cta }));
        mount.appendChild(counts);

        var issueMount = ids.issueList;
        issueMount.replaceChildren();

        if (!result.issues.length) {
          issueMount.appendChild(node("div", { class: "pill good", text: "Coverage looks usable. Shoot anything still marked needed." }));
          return;
        }

        result.issues.forEach(function (issue) {
          issueMount.appendChild(node("div", { class: "pill " + issue.severity, text: issue.text }));
        });
      }

      function buildChecklist() {
        var result = analyze();
        var lines = [];
        var today = new Date();

        lines.push("YOUTUBE B-ROLL SHOOT CHECKLIST");
        lines.push("Generated: " + today.toLocaleString());
        lines.push("");
        lines.push("PREMISE");
        lines.push(clean(state.premise) || "[add premise]");
        lines.push("");
        lines.push("AUDIENCE / VIEWER PROBLEM");
        lines.push(clean(state.audience) || "[add audience]");
        lines.push("");
        lines.push("VIDEO STYLE");
        lines.push(state.style || "practical");
        lines.push("");
        lines.push("VIEWER ACTION");
        lines.push(clean(state.action) || "[add viewer action]");
        lines.push("");
        lines.push("COVERAGE SCORE");
        lines.push(String(result.score) + "/100");
        lines.push("");

        lines.push("MISSING COVERAGE / PICKUPS");
        if (result.issues.length) {
          result.issues.forEach(function (issue) {
            lines.push("- " + issue.text);
          });
        } else {
          lines.push("- No major coverage gaps flagged.");
        }
        lines.push("");

        ["intro", "body", "proof", "cta"].forEach(function (slotId) {
          var slotShots = state.shots.filter(function (shot) {
            return shot.slot === slotId && shot.status !== "skip";
          });

          lines.push(slotName(slotId).toUpperCase());

          if (!slotShots.length) {
            lines.push("- [ ] Missing cards for this slot.");
          } else {
            slotShots.forEach(function (shot) {
              var box = shot.status === "shot" ? "[x]" : "[ ]";
              var critical = shot.critical ? " CRITICAL" : "";
              lines.push("- " + box + critical + " " + oneLine(shot.label));
              lines.push("  Detail: " + (oneLine(shot.detail) || "[add detail]"));
              lines.push("  Source: " + sourceTitle(shot.sourceId));
            });
          }

          lines.push("");
        });

        var poolShots = state.shots.filter(function (shot) {
          return shot.slot === "pool" && shot.status !== "skip";
        });

        lines.push("UNDEALT CARDS");
        if (!poolShots.length) {
          lines.push("- None.");
        } else {
          poolShots.forEach(function (shot) {
            lines.push("- [ ] " + oneLine(shot.label) + " — " + sourceTitle(shot.sourceId));
          });
        }
        lines.push("");

        lines.push("SCENES AND CLAIMS");
        if (!state.items.length) {
          lines.push("- [ ] Add scenes or claims.");
        } else {
          state.items.forEach(function (item) {
            lines.push("- " + item.kind.toUpperCase() + ": " + oneLine(item.title));
            lines.push("  Priority: " + item.priority);
            lines.push("  Notes: " + (oneLine(item.notes) || "[none]"));
            lines.push("  Evidence: " + (oneLine(item.evidence) || "[missing]"));
          });
        }

        return lines.join("\n");
      }

